local nzComponents = script.Parent.Parent.components
local module = {}

local _components = {}
local _cacheComponents = {}

local function _loadNz()
    local components = {}
    for i, v in pairs(nzComponents:GetChildren()) do
        components[v.Name] = require(v)
    end
    return components
end

function module.Get(element, componentName, ...)
    componentName = componentName or element.ClassName
    local component = _components[componentName]
    if component then
        local has, obj = module.Has(element, componentName)
        if has then
            if obj.OnComponentGet then
                obj:OnComponentGet(...)
            end
            return obj
        end
        obj = component.new(element)
        if not _cacheComponents[element] then
            _cacheComponents[element] = {}
        end
        _cacheComponents[element][componentName] = obj
        if component.GetContent then
            obj.Content = element
            obj.GetContent = function(self)
                return self.Content
            end
        end
        if obj.OnComponentGet then
            obj:OnComponentGet(...)
        end
        return obj
    else
        warn(`[NezaUI] Component {componentName} not found`)
    end
    return nil
end

function module.Has(element, componentName)
	componentName = componentName or element.ClassName
    if not _cacheComponents[element] then
        return false
    end
    if not _cacheComponents[element][componentName] then
		return false
	end
    return true, _cacheComponents[element][componentName]
end

-- 添加自定义Component
function module.LoadComponent(name, componentModuleScript)
    local class = require(script.Parent.Parent.apis.class)
    local BaseComponent = require(script.Parent.Parent.apis.BaseComponent)
    local module = class(name, BaseComponent)
    local component
    if typeof(componentModuleScript) == "Instance" and componentModuleScript:IsA("ModuleScript") then
        component = require(componentModuleScript:Clone())
    elseif typeof(componentModuleScript) == "table" then
        component = componentModuleScript
    end
    if component then
        for i, v in pairs(component) do
            module[i] = v
        end
        _components[name] = module
    end
end

_components = _loadNz()
return module